let _markdown = "\n\nIntroduction [#introduction]\n\n<FeedbackBlock\n  id=\"647a8e2a11b4782b\"\n  body=\"Fumadocs (Foo-ma docs) is a documentation framework, designed to be fast, flexible,\nand composes seamlessly into your React framework.\"\n>\n  Fumadocs <span className=\"text-fd-muted-foreground text-sm\">(Foo-ma docs)</span> is a **documentation framework**, designed to be fast, flexible,\n  and composes seamlessly into your React framework.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"e2a6c85477e024aa\" body=\"Fumadocs has different parts:\">\n  Fumadocs has different parts:\n</FeedbackBlock>\n\n<Cards>\n  <Card icon={<CpuIcon className=\"text-purple-300\" />} title=\"Fumadocs Core\" href=\"/docs/headless\">\n    Handles most of the logic, including document search, content source adapters, and Markdown extensions.\n  </Card>\n\n  <Card icon={<PanelsTopLeft className=\"text-blue-300\" />} title=\"Fumadocs UI\" href=\"/docs/ui\">\n    The default theme of Fumadocs offers a beautiful look for documentation sites and interactive components.\n  </Card>\n\n  <Card icon={<Database />} title=\"Content Source\">\n    The source of your content, can be a CMS or local data layers like [Fumadocs MDX](/docs/mdx) (the official content source).\n  </Card>\n\n  <Card icon={<Terminal />} title=\"Fumadocs CLI\" href=\"/docs/cli\">\n    A command line tool to install UI components and automate things, useful for customizing layouts.\n  </Card>\n</Cards>\n\n<Callout title=\"Want to learn more?\">\n  Read our in-depth [What is Fumadocs](/docs/what-is-fumadocs) introduction.\n</Callout>\n\nTerminology [#terminology]\n\n<FeedbackBlock id=\"725700dbda867115\" body=\"Markdown/MDX: Markdown is a markup language for creating formatted text. Fumadocs natively supports Markdown and MDX (superset of Markdown).\">\n  **Markdown/MDX:** Markdown is a markup language for creating formatted text. Fumadocs natively supports Markdown and MDX (superset of Markdown).\n</FeedbackBlock>\n\n<FeedbackBlock id=\"c60d679f1e312845\" body=\"Bun: A JavaScript runtime, we use it for running scripts.\">\n  **[Bun](https://bun.sh):** A JavaScript runtime, we use it for running scripts.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"64125cfec9289987\" body=\"Some basic knowledge of React.js would be useful for further customisations.\">\n  Some basic knowledge of React.js would be useful for further customisations.\n</FeedbackBlock>\n\nAutomatic Installation [#automatic-installation]\n\n<FeedbackBlock id=\"0369d25e54cba52e\" body=\"A minimum version of Node.js 22 required.\">\n  A minimum version of Node.js 22 required.\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"npm\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"npm\">\n      npm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"pnpm\">\n      pnpm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"yarn\">\n      yarn\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"bun\">\n      bun\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"npm\">\n    ```bash\n    npm create fumadocs-app\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"pnpm\">\n    ```bash\n    pnpm create fumadocs-app\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"yarn\">\n    ```bash\n    yarn create fumadocs-app\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"bun\">\n    ```bash\n    bun create fumadocs-app\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\n<FeedbackBlock id=\"f7d1b73a1d517bd4\" body=\"It will ask you the built-in template to use:\">\n  It will ask you the built-in template to use:\n</FeedbackBlock>\n\n<FeedbackBlock id=\"c9218a3240875c89\" body=\"React.js framework: Next.js, Waku, React Router, Tanstack Start.Content source: Fumadocs MDX.\">\n  * **React.js framework**: Next.js, Waku, React Router, Tanstack Start.\n  * **Content source**: Fumadocs MDX.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"998344b5b33a3574\" body=\"A new fumadocs app should be initialized. Now you can start hacking!\">\n  A new fumadocs app should be initialized. Now you can start hacking!\n</FeedbackBlock>\n\n<Callout title=\"From Existing Codebase?\">\n  You can follow the [Manual Installation](/docs/manual-installation) guide to get started.\n</Callout>\n\nEnjoy! [#enjoy]\n\n<FeedbackBlock id=\"a5f99088c987359e\" body=\"Create your first MDX file in the docs folder.\">\n  Create your first MDX file in the docs folder.\n</FeedbackBlock>\n\n```mdx title=\"content/docs/index.mdx\"\n---\ntitle: Hello World\n---\n\n## Yo what's up\n```\n\n<FeedbackBlock id=\"53f523dbdc7e1213\" body=\"Run the app in development mode and see http://localhost:3000/docs.\">\n  Run the app in development mode and see [http://localhost:3000/docs](http://localhost:3000/docs).\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"npm\" groupId=\"package-manager\" persist>\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"npm\">\n      npm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"pnpm\">\n      pnpm\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"yarn\">\n      yarn\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"bun\">\n      bun\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"npm\">\n    ```bash\n    npm run dev\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"pnpm\">\n    ```bash\n    pnpm run dev\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"yarn\">\n    ```bash\n    yarn dev\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"bun\">\n    ```bash\n    bun run dev\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\nFAQ [#faq]\n\n<FeedbackBlock id=\"6356d46515789a9e\" body=\"Some common questions you may encounter.\">\n  Some common questions you may encounter.\n</FeedbackBlock>\n\n<Accordions>\n  <Accordion id=\"upgrade-fumadocs\" title=\"Getting error with missing APIs or bugs?\">\n    Make sure to upgrade Fumadocs when you've encountered any problems or trying out new features:\n\n    ```bash title=\"pnpm\"\n    pnpm update -i -r --latest\n    ```\n  </Accordion>\n\n  <Accordion id=\"change-base-url\" title=\"How to change the base route of docs?\">\n    Routing is handled by your React framework, you need to change the routing structure first.\n\n    For example, in Next.js, rename the route (`/docs/*` -> `/info/*`):\n\n    <Files>\n      <Folder name=\"app/docs\" defaultOpen className=\"opacity-50\" disabled>\n        <File name=\"layout.tsx\" />\n      </Folder>\n\n      <Folder name=\"app/info\" defaultOpen>\n        <File name=\"layout.tsx\" />\n      </Folder>\n    </Files>\n\n    Or rename from `/docs/*` to `/*` using a route group:\n\n    <Files>\n      <Folder name=\"app/(docs)\" defaultOpen>\n        <File name=\"layout.tsx\" />\n      </Folder>\n    </Files>\n\n    Finally, update the base URL of pages in `source.ts`:\n\n    ```ts title=\"lib/source.ts\"\n    import { loader } from 'fumadocs-core/source';\n\n    export const source = loader({\n      baseUrl: '/info', // to the new value [!code highlight]\n    });\n    ```\n  </Accordion>\n\n  <Accordion id=\"multi-docs\" title=\"How to implement multi-docs?\">\n    We recommend to use [Sidebar Tabs](/docs/ui/layouts/docs#sidebar-tabs).\n  </Accordion>\n</Accordions>\n\nFor Vite [#for-vite]\n\n<Accordions>\n  <Accordion id=\"vite-context-error\" title=\"Getting error with React contexts?\">\n    There's some weird pre-bundling problems with Vite: [#3910](https://github.com/vitejs/vite/issues/3910).\n    Make sure to exclude Fumadocs from pre-bundling and add it to `noExternal`:\n\n    ```ts title=\"vite.config.ts\"\n    import { defineConfig } from 'vite';\n\n    export default defineConfig({\n      resolve: {\n        // add other Fumadocs deps as needed\n        noExternal: [\n          'fumadocs-core',\n          'fumadocs-ui',\n          'fumadocs-openapi',\n          '@fumadocs/base-ui',\n          '@fumadocs/ui',\n        ],\n      },\n    });\n    ```\n  </Accordion>\n</Accordions>\n\nFor Next.js [#for-nextjs]\n\n<Accordions>\n  <Accordion id=\"node-23\" title=\"Getting error on production build?\">\n    Node.js 23.1 might have problems with Next.js, see [#1021](https://github.com/fuma-nama/fumadocs/issues/1021). Make sure to change your Node.js version.\n  </Accordion>\n\n  <Accordion id=\"dynamic-route\" title=\"It uses Dynamic Route, will it be poor in performance?\">\n    Next.js turns dynamic route into static routes when `generateStaticParams` is configured.\n    Hence, it is as fast as static pages.\n\n    You can [enable Static Exports](/docs/deploying/static) on Next.js to get a static build output.\n  </Accordion>\n\n  <Accordion id=\"webpack\" title=\"Reading from &#x22;fumadocs-mdx:collections/server&#x22; is not handled by plugins\">\n    Webpack resolves import namespace **before** your import aliases in `tsconfig.json`. When using Fumadocs MDX, you have to rename your import alias to `collections/*` instead.\n\n    ```json title=\"tsconfig.json\"\n    {\n      \"compilerOptions\": {\n        \"paths\": {\n          // [!code ++]\n          \"collections/*\": [\".source/*\"]\n        }\n      }\n    }\n    ```\n\n    Make sure to update the references as well.\n\n    ```ts title=\"lib/source.ts\"\n    // [!code --]\n    import { docs } from 'fumadocs-mdx:collections/server';\n    // [!code ++]\n    import { docs } from 'collections/server';\n    ```\n  </Accordion>\n\n  <Accordion id=\"custom-layout-docs-page\" title=\"How to create a page in /docs without docs layout?\">\n    Same as managing layouts in Next.js App Router, remove the original MDX file from content directory (`/content/docs`).\n    This ensures duplicated pages will not cause errors.\n\n    Now, You can add the page to another route group, which isn't a descendant of docs layout.\n\n    For example, to replace `/docs/test`:\n\n    <Files>\n      <File name=\"(home)/docs/test/page.tsx\" />\n\n      <Folder name=\"docs\" defaultOpen>\n        <File name=\"layout.tsx\" />\n\n        <File name=\"[[...slug]]/page.tsx\" />\n      </Folder>\n    </Files>\n\n    For `/docs`, you need to change the catch-all route to be non-optional:\n\n    <Files>\n      <File name=\"(home)/docs/page.tsx\" />\n\n      <Folder name=\"docs\" defaultOpen>\n        <File name=\"layout.tsx\" />\n\n        <File name=\"[...slug]/page.tsx\" />\n      </Folder>\n    </Files>\n  </Accordion>\n</Accordions>\n\nLearn More [#learn-more]\n\n<FeedbackBlock id=\"da72f23da565be9d\" body=\"New to here? Don't worry, we are welcome for your questions.\">\n  New to here? Don't worry, we are welcome for your questions.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"e40d35b3284f2c34\" body=\"If you find anything confusing, please give your feedback on Github Discussion!\">\n  If you find anything confusing, please give your feedback on [Github Discussion](https://github.com/fuma-nama/fumadocs/discussions)!\n</FeedbackBlock>\n\nWriting Content [#writing-content]\n\n<FeedbackBlock id=\"5874cd767894da99\" body=\"For authoring docs, make sure to read:\">\n  For authoring docs, make sure to read:\n</FeedbackBlock>\n\n<Cards>\n  <Card href=\"/docs/markdown\" title=\"Markdown\">\n    Fumadocs has some additional features for authoring content.\n  </Card>\n\n  <Card href=\"/docs/navigation\" title=\"Navigation\">\n    Learn how to customise navigation structure.\n  </Card>\n\n  <Card href=\"/docs/page-conventions\" title=\"Page Slugs & Page Tree\">\n    Learn how to organise content.\n  </Card>\n\n  <Card href=\"/docs/ui/components\" title=\"Components\" description=\"See all available components to enhance your docs\" />\n</Cards>\n\nSpecial Needs [#special-needs]\n\n<Cards>\n  <Card href=\"/docs/deploying/static\" title=\"Configure Static Export\" description=\"Learn how to enable static export on your docs\" />\n\n  <Card href=\"/docs/internationalization\" title=\"Internationalization\" description=\"Learn how to enable i18n\" />\n\n  <Card href=\"/docs/ui/theme\" title=\"Color Themes\" description=\"Add themes to Fumadocs UI\" />\n\n  <Card href=\"/docs/ui/layouts\" title=\"Layouts\" description=\"Customise your Fumadocs UI layouts\" />\n</Cards>\n";
